from .base import ObjectStore


class InMemoryStore(ObjectStore):
    """S3-shaped store in a dict. Pinned by tests/test_store_contract.py, which also runs on MinIO."""

    def __init__(self) -> None:
        self.buckets: dict[str, dict[str, bytes]] = {}

    def create_bucket(self, bucket: str) -> None:
        self.buckets.setdefault(bucket, {})

    def put(self, bucket: str, key: str, data: bytes) -> None:
        self.buckets[bucket][key] = data  # a missing bucket raises KeyError, like MinIO raises NoSuchBucket

    def get(self, bucket: str, key: str) -> bytes:
        return self.buckets[bucket][key]

    def list_keys(self, bucket: str, prefix: str = "") -> list[str]:
        return sorted(key for key in self.buckets[bucket] if key.startswith(prefix))

class FakeOnPremClient(RhinoCloudInternalRpcProxyServicer):
    def __init__(self):
        self.calls: list[tuple[str, str]] = []  # (rhino_agent_id, method_name)
        self.offline_agents: set[str] = set()
        self.scheduled: list[onprem.ScheduleTaskRequest] = []

    def AgentRpc(self, request, context):  # runs on a gRPC server thread: never touch the database here
        self.calls.append((request.rhino_agent_id, request.method_name))
        if request.rhino_agent_id in self.offline_agents:
            return AgentRpcResponse(error_message="agent not connected", error_type=AgentRpcResponse.ErrorType.TIMEOUT)
        handler = getattr(self, f"_{request.method_name}", None)
        if handler is None:  # loud on purpose: add the method here and a case to the contract suite
            return AgentRpcResponse(error_message=f"FakeOnPremClient does not implement {request.method_name}")
        request_type = getattr(onprem, METHODS[request.method_name].input_type.name)
        return AgentRpcResponse(response_data=handler(request_type.FromString(request.request_data)).SerializeToString())

    def _HealthCheck(self, request):
        return onprem.HealthCheckResponse(is_healthy=True)

class FakeTaskQueue:
    def __init__(self):
        self.sent: list[SentTask] = []
        self.ran: list[SentTask] = []

    def send_task(self, name, args=None, kwargs=None, task_id=None, **options):  # replaces app.send_task
        content_type, encoding, body = dumps((args or (), kwargs or {}), serializer=app.conf.task_serializer)
        args, kwargs = loads(body, content_type, encoding, accept=app.conf.accept_content)
        self.sent.append(SentTask(name, tuple(args), kwargs, options, task_id or str(uuid.uuid4())))
        return app.AsyncResult(self.sent[-1].task_id)  # callers read .id; tests call drain(), never .get()

    def drain(self) -> list[SentTask]:
        while self.sent:
            task = self.sent.pop(0)
            result = app.tasks[task.name].apply(task.args, task.kwargs, task_id=task.task_id, headers=task.options.get("headers"))
            result.get(propagate=True)  # the task's own exception, raised in the test
            if chain := list(task.options.get("chain") or []):
                next_sig = maybe_signature(chain.pop(), app=app)  # Celery keeps the rest of a chain reversed
                next_sig.apply_async(() if next_sig.immutable else (result.result,), chain=chain or None)
            self.ran.append(task)
        return self.ran
